window.REPORT_PRELOAD_CACHE["CROX.html"] = {"version":"ca4f43cc4820417219fc6a8048d7a88c0646be4b2461f50b9b75ac80230ca840","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>卡骆驰 Crocs, Inc. (NASDAQ: CROX) 深度研究报告：从洞洞鞋文化符号到全球高毛利现金流与“食人族”回购复利机器</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            croxgreen: {\n              400: '#A3E635',\n              500: '#65A30D',\n              600: '#4D7C0F',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              400: '#22D3EE',\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微上移 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(101, 163, 13, 0.25) 0%, rgba(6, 182, 212, 0.08) 100%);\n      border-left: 3px solid #A3E635;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-croxgreen-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-croxgreen-500 via-croxgreen-400 to-teal-500 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-croxgreen-400 to-croxgreen-600 flex items-center justify-center font-extrabold text-navy-950 text-xs shadow\">\n        CX\n      </div>\n      <div>\n        <div class=\"text-[11px] text-croxgreen-400 font-semibold tracking-wider uppercase\">NASDAQ: CROX · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">卡骆驰 Crocs 深度研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">CROX 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球可选消费与品牌服饰鞋履研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / FY26E-27E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-croxgreen-400 to-croxgreen-600 flex items-center justify-center text-navy-950 font-extrabold text-sm shadow-lg shadow-croxgreen-500/25\">\n            CROX\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-croxgreen-400 bg-croxgreen-500/15 px-2 py-0.5 rounded\">NASDAQ: CROX</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">卡骆驰深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          全球洞洞鞋文化符号 · 60%+ 高毛利现金流与“食人族”回购复利机器\n        </p>\n      </div>\n\n      <!-- 股票实时快照徽章 -->\n      <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">参考股价 / 市值</span>\n          <span class=\"font-mono font-bold text-white\">$163.72 <span class=\"text-slate-400\">/ $7.27B</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">FY26E 调整后 EPS</span>\n          <span class=\"font-mono font-bold text-croxgreen-400\">$14.45–$14.65 <span class=\"text-slate-400\">(+16%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">远期估值与现金流</span>\n          <span class=\"font-mono font-bold text-teal-400\">~11.2x P/E · FCF Yield 10.4%</span>\n        </div>\n      </div>\n\n      <!-- 七大核心章节目录导航 -->\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-croxgreen-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-croxgreen-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-croxgreen-400 hover:bg-croxgreen-500 text-navy-950 text-xs font-extrabold transition shadow-sm cursor-pointer\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. Hero 研报封面区与执行摘要\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元数据标签栏 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 font-bold border border-croxgreen-500/30\">评级：强烈买入 / 高现金流价值成长重仓</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2027 双品牌共振与国际扩张</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>NASDAQ: CROX ($163.72 · 52W $73.21–$164.13)</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <!-- 背景鳄鱼青柠绿点阵纹理 -->\n          <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#A3E635 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-croxgreen-500/20 border border-croxgreen-400/40 text-croxgreen-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-croxgreen-400 animate-pulse\"></span>\n              <span>CORE THESIS · HEYDUDE 迎来 +6.1% 正增长拐点 × 国际 DTC 暴增 24% × 十年注销 37% 股本的现金流复利机</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              卡骆驰 Crocs, Inc. (NASDAQ: CROX) 深度研究报告：从洞洞鞋文化符号到全球高毛利现金流与“食人族”回购复利机器\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              2026年10月底公布的 Q3 财报成为 CROX 全面重估的分水岭——集团单季营收达 <strong class=\"text-white\">$1,043M (+4.6% YoY)</strong>，调整后摊薄 EPS 跃升至 <strong class=\"text-croxgreen-400\">$3.69 (+26.4% YoY)</strong>，年内连续第三次上调全年指引（FY26E 调整后 EPS <strong class=\"text-white\">$14.45–$14.65</strong>）。\n              困扰市场两年的收购品牌 <strong class=\"text-croxgreen-400\">HEYDUDE 单季营收同比增长 +6.1%（批发大增 +14%）正式迎来反转拐点</strong>；Crocs 主品牌在国际市场（中、印、日领跑）实现 <strong class=\"text-teal-400\">~12% 增长（国际 DTC 暴增 24%）</strong>。凭借 <strong class=\"text-white\">~60.3%</strong> 的奢侈品级调整后毛利率、超 <strong class=\"text-teal-400\">$7.5亿</strong> 年化自由现金流及剩余 <strong class=\"text-croxgreen-400\">$17亿</strong> 股票回购授权（约占当前 $7.27B 市值 23%），当前 <strong class=\"text-emerald-400\">~11.2x P/E</strong> 仍具显著重估弹性。\n            </p>\n\n            <!-- 核心投资结论高亮条 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">HEYDUDE 反转拐点确立</div>\n                <div class=\"text-white font-semibold\">2025年计提 $7.37亿 减值彻底出清历史包袱，26Q3 增长 +6.1%，26Q4 指引进一步加速至 +10%~12%</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">国际扩张与社交电商引擎</div>\n                <div class=\"text-croxgreen-400 font-semibold\">国际营收突破 $17亿+ 逼近北美，AI导购 Agent \"Rivet\" 与 TikTok Shop 驱动 $50–$60 黄金价格带高频转化</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">“食人族”股本注销引擎</div>\n                <div class=\"text-teal-400 font-semibold\">过去十年累计回购 ~$30亿、缩减 37% 股本，26Q3 稀释股本同比再降 11.9% 至 4,600 万股，剩余授权 $17亿</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2026E 预期总营收</span>\n              <span class=\"p-1.5 rounded-lg bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$4.16B</span>\n              <span class=\"text-xs font-bold text-croxgreen-600 dark:text-croxgreen-400 bg-croxgreen-500/15 px-2 py-0.5 rounded\">+3.0% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              26Q4 营收指引加速至 +7%~9%，Crocs 主品牌在旺季单季营收已突破 $10亿 里程碑。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>调整后毛利率 & 营业利润率</span>\n              <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">60.3%</span>\n              <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">OPM &gt;22.5%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              26Q3 GAAP 毛利率受 $64M 关税退税提振高达 66.2%，常态化盈利能力稳居全球鞋服塔尖。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2026E 调整后摊薄 EPS</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$14.55</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">+16.3% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              全年指引区间 $14.45–$14.65（年内连续第三次上调），26Q3 单季 EPS 同比飙升 +26.4%。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>TTM 自由现金流 & 远期估值</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$754M</span>\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">Fwd P/E ~11.2x</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              自由现金流收益率高达 ~10.4%，剩余 $17亿 股票回购授权足以再注销逾五分之一流通股。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-croxgreen-600 dark:text-croxgreen-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：国际引擎领跑主品牌，HEYDUDE 迎来历史性反转</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26E 预期营收 ~$4.16B · DTC 直营渠道占比 ~53.5%</span>\n        </div>\n\n        <!-- 交互式 Chart.js 双视图切换面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：双视图图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2021–FY2027E 双品牌营收演进与 HEYDUDE 触底回升</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">Crocs 主品牌稳步迈向 $3.60B，HEYDUDE 历经两年渠道出清后于 26H2 重回正增长轨道</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-croxgreen-600 dark:text-croxgreen-400 shadow-sm transition cursor-pointer\">视图A：双品牌演进</button>\n                <button onclick=\"switchBizChart('split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：区域与渠道拆解</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：结构性拆解核心洞察 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性拐点</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">Crocs 国际营收占比跃升至 ~51%，中印日一级市场爆发</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      国际业务年化规模突破 <strong>$17.6亿</strong> 首度反超北美本土；26Q3 国际整体增长 ~12%，其中<strong>国际 DTC 直营暴增 +24%</strong>，中国、印度与日本市场渗透率仍处于早期甜蜜点。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">HEYDUDE 渠道库存清理完毕，批发补库大增 +14%</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      关闭低效灰色分销与折扣清理后，HEYDUDE 在 26Q3 实现 <strong>+6.1%</strong> 同比转正（批发营收 +14%），管理层指引 26Q4 营收增速将进一步提速至 <strong>+10%–12%</strong>。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">社交电商霸主与 AI 购物助手 “Rivet” 落地增效</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      稳居 TikTok Shop 鞋服类目头部阵营，并率先在官网与 App 部署生成式 AI 导购 Agent <strong>“Rivet”</strong>，实现鞋款尺码精准匹配与 Jibbitz 个性化搭配推荐，显著拉升客单价与转化率。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">2026Q4 核心增长指引</span>\n              <span class=\"font-bold text-croxgreen-600 dark:text-croxgreen-400\">集团营收 +7%~9% · HEYDUDE +10%~12%</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 业务分部详细卡片矩阵 (2+1+3 = 6格完美对齐) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- 分部 1：Crocs 主品牌 (占两列宽度突出绝对支柱地位) -->\n          <div class=\"md:col-span-2 report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-croxgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n              <div class=\"flex items-center space-x-2\">\n                <span class=\"px-2.5 py-1 rounded-md bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 text-xs font-bold\">集团核心现金牛 · 营收占比 ~83%</span>\n                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">国际 DTC +24% YoY</span>\n              </div>\n              <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">FY26E 营收：~$3.46B</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. Crocs 卡骆驰主品牌（Classic Clog 经典洞洞鞋 + 国际高增引擎）</h3>\n            <div class=\"mt-3 grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">北美稳健防御（~$1.70B）· 高利润现金池</div>\n                <p class=\"leading-relaxed\">\n                  北美家庭渗透率高但复购周期稳定，公司主动严控促销折扣以捍卫 62%+ 品牌毛利率，通过厚底增高款（ Bae / Mega Crush ）及专业医护厨师工作鞋稳固基本盘。\n                </p>\n              </div>\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">国际高速扩张（~$1.76B）· 渗透率红利释放</div>\n                <p class=\"leading-relaxed\">\n                  国际人均持有量仅为北美的 1/4 至 1/3。凭借本土化明星代言、百货快闪店与抖音/TikTok 直播矩阵，中国、印度、日本及西欧市场延续双位数强劲增长。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- 分部 2：HEYDUDE 休闲鞋 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">占比 ~17% · 26Q3 +6.1% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$0.72B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. HEYDUDE 超轻休闲一脚蹬</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                主打 Wendy 与 Wally 超轻舒适乐福鞋。经历 2024–2025 年严厉整顿亚马逊乱价与批发去库（并计提 $7.37亿 非现金商誉商标减值）后，26Q3 批发大增 <strong>+14%</strong>，女性年轻客群破圈成效显著。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n              减值包袱出清 · 26Q4 指引提速至 +10%~12%\n            </div>\n          </div>\n\n          <!-- 分部 3：Jibbitz 智必星个性化配饰生态 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-croxgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 text-xs font-bold\">超高毛利增强器 · 配件复购飞轮</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$280M+</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. Jibbitz™（智必星）鞋花生态</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                每双经典洞洞鞋拥有 <strong>26 个透气孔位</strong>，单颗售价 $4.99–$9.99 的 Jibbitz 鞋花毛利率高达 <strong>75%–80%+</strong>。不仅直接拉升连带率与客单价，更让消费者免费成为品牌社交内容创作者。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-croxgreen-600 dark:text-croxgreen-400 font-semibold\">\n              低单价高频盲盒属性 · 独一无二 DIY 壁垒\n            </div>\n          </div>\n\n          <!-- 分部 4：凉鞋与四季新品类矩阵 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">TAM 扩容抓手 · $300亿全球凉鞋市场</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$450M+</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. 时尚凉鞋与多元廓形（Sandals & Echo）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                依托 Brooklyn 厚底凉鞋、Getaway 极简人字拖、Mellow 运动恢复拖鞋及 Echo 街头机能系列，成功打破“单一洞洞鞋款式依赖”，打开对时尚女性与潮流男性群体的全天候穿搭覆盖。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n              对冲单一鞋型审美疲劳 · 切入高频夏日穿搭\n            </div>\n          </div>\n\n          <!-- 分部 5：DTC 数字化与社交直营矩阵 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">直营占比 53.5% · AI 导购赋能</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$2.23B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">5. 全球全渠道 DTC（奥莱 + 社交电商 + Rivet）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                超过半数收入来自高坪效线下门店、奥特莱斯及自营电商/TikTok Shop。直面消费者使公司第一时间捕捉爆款配色信号，并通过 AI 助手 <strong>Rivet</strong> 实现千人千面的动态交叉销售。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n              掌握终端定价权 · 第一方消费者数据闭环\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 行业地位与四重核心护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：注塑物理极简主义与社交飞轮共振</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：结构性成本优势 + 文化定制生态 (Molded Footwear Global #1)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四重护城河深度解析 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 护城河 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Croslite™ 一体注塑工艺与极致成本结构</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                传统运动鞋需数十种面料裁片与密集人工车缝，而 Crocs 采用专利封闭细胞树脂 <strong>Croslite™ / LiteRide™ 模具一体注塑成型</strong>，单鞋制造成本仅数美元、无复杂尺码半码冗余，造就 <strong>60%+ 奢侈品级毛利率</strong>与极低过季减值风险。\n              </p>\n            </div>\n\n            <!-- 护城河 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Jibbitz™ 配饰生态与 Z 世代 DIY 社交画布</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                白牌竞品虽能模仿外观，却无法复制正版洞洞鞋的<strong>社交身份认同与 Jibbitz 授权 IP 生态</strong>。功能性鞋履被转化为“脚上的个性手账”，高毛利鞋花持续驱动存量用户低门槛复购与自发晒单裂变。\n              </p>\n            </div>\n\n            <!-- 护城河 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨界联名引擎与 $50–$60 抗通胀“口红效应”</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                每年推出超 60 款现象级联名（从巴黎世家、Salehe Bembury 到麦当劳、宝可梦、漫威），顶流话题热度向下反哺 <strong>$50–$60 大众主力价格带</strong>——相较动辄 $150+ 的运动鞋，具备极强的抗经济周期韧性与冲动消费转化力。\n              </p>\n            </div>\n\n            <!-- 护城河 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">轻资产高现金转化与敏捷快反补单（At-Once）</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                采用高度分散的第三方代工（越南、印尼、印度、墨西哥等），年度 CapEx 仅 <strong>$50M–$80M（不足营收 2%）</strong>，超 80% EBITDA 直接转化为自由现金流；模具化生产支持季内极速快反补货，深受零售批发商青睐。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球鞋履行业五维商业模型量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Crocs (CROX) vs 高端特色鞋履 (DECK/BIRK) vs 传统大众运动巨头（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比 (Competitive Landscape)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-croxgreen-600 dark:text-croxgreen-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：塔尖级 22.5% 营业利润率 vs 仅 11x 极端折价</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-croxgreen-400 text-navy-950 shadow-sm transition cursor-pointer\">全部鞋履同行</button>\n            <button onclick=\"filterCompetitors('specialty')\" data-filter=\"specialty\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">高毛利特色鞋履 (DECK/BIRK)</button>\n            <button onclick=\"filterCompetitors('highgrowth')\" data-filter=\"highgrowth\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">高成长运动新贵 (ONON)</button>\n            <button onclick=\"filterCompetitors('traditional')\" data-filter=\"traditional\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">传统运动与休闲巨头 (NKE/SKX)</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[180px]\">鞋履巨头与核心品牌矩阵</th>\n                  <th class=\"py-4 px-4 min-w-[115px]\">毛利率水平</th>\n                  <th class=\"py-4 px-4 min-w-[120px]\">营业利润率</th>\n                  <th class=\"py-4 px-4 min-w-[120px]\">远期 P/E 估值</th>\n                  <th class=\"py-4 px-4 min-w-[145px]\">资本回报与现金流特征</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞合定位评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：Crocs (CROX) 基准 -->\n                <tr data-category=\"core\" class=\"bg-croxgreen-500/5 dark:bg-croxgreen-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-croxgreen-400 text-navy-950 text-[10px] font-extrabold\">核心标的</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">Crocs, Inc. (CROX)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Crocs / HEYDUDE / Jibbitz™</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-croxgreen-600 dark:text-croxgreen-400\">~60.3%</td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~22.5%+</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">~11.2x (显著低估)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-semibold text-teal-600 dark:text-teal-400\">FCF Yield ~10.4% · 激进回购</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>高现金流性价比之王：</strong>拥有与 DECK/BIRK 相当的 60% 毛利与 22.5% 营业利润率，估值却不足同行一半；随 HEYDUDE 转正，估值折价亟待收敛。\n                  </td>\n                </tr>\n\n                <!-- 行 2：Deckers Outdoor (DECK) -->\n                <tr data-category=\"specialty\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Deckers Outdoor (DECK)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">HOKA (专业跑鞋) / UGG (雪地靴)</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~57.5%</td>\n                  <td class=\"py-4 px-4 font-mono font-semibold text-slate-900 dark:text-white\">~23.7%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~24.5x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">净现金资产负债表 · 稳健回购</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>双品牌运营教科书：</strong>HOKA 高速成长与 UGG 强劲品牌力令其享有 24x+ 溢价，证明市场愿意为成功的双品牌鞋企赋予高倍数。\n                  </td>\n                </tr>\n\n                <!-- 行 3：Birkenstock (BIRK) -->\n                <tr data-category=\"specialty\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Birkenstock (BIRK)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Boston 勃肯包头鞋 / Arizona 软木凉鞋</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~59.2%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~21.0%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~22.8x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">欧洲自建工厂重资产 · 降债为主</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>最直接舒适鞋履对标：</strong>定位 $110–$170 中高端软木鞋床，LVMH 关联背景加持品牌溢价，但重资产扩产导致自由现金流转化率不及 CROX。\n                  </td>\n                </tr>\n\n                <!-- 行 4：On Holding (ONON) -->\n                <tr data-category=\"highgrowth\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">On Holding 昂跑 (ONON)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Cloudmonster / Cloudtilt 中产跑鞋</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~60.5%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~13.2%</td>\n                  <td class=\"py-4 px-4 font-mono text-accent-600 dark:text-accent-400\">~35.0x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">高营销与门店投入期 · 无回购</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>高成长溢价代表：</strong>营收增速超 25% 领跑全球运动鞋，但高昂营销与直营开店费用使营业利润率较 CROX 低逾 9 个百分点，估值容错率较低。\n                  </td>\n                </tr>\n\n                <!-- 行 5：Nike (NKE) -->\n                <tr data-category=\"traditional\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Nike 耐克 (NKE)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Nike / Jordan / Converse</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~44.0%</td>\n                  <td class=\"py-4 px-4 font-mono text-rose-600 dark:text-rose-400\">~8.4%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~26.0x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">股息率 ~2.2% · 盈利处于转型低谷</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>巨头转型阵痛期：</strong>经典复古鞋清库存与重返批发渠道仍在推进，营业利润率跌破双位数，但市场仍给予其高达 26x 品牌信仰估值。\n                  </td>\n                </tr>\n\n                <!-- 行 6：Skechers / Columbia 大众休闲阵营 -->\n                <tr data-category=\"traditional\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Skechers / Columbia 大众休闲</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Slip-ins 闪穿鞋 / 户外大众鞋服</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~51.5%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~9.4%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~14.5x – 16.0x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">重物流分销投入 · 温和股东回报</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>高性价比实用主义竞争者：</strong>斯凯奇一脚蹬与 HEYDUDE 在舒适日常通勤场景存在直接交集，但整体营业利润率与单店坪效远逊于 CROX。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- 配套 Chart.js 横向条形图：营业利润率对比 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要上市鞋服巨头营业利润率（Operating Margin %）横向对比</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">CROX 以 22.5% 营业利润率紧随 DECK 位居全球第二，估值（~11.2x）却仅为同梯队利润率同行的一半</p>\n            </div>\n            <span class=\"text-xs font-semibold text-croxgreen-600 dark:text-croxgreen-400 bg-croxgreen-500/15 px-2.5 py-1 rounded\">塔尖级盈利能力 × 极端估值折价反差</span>\n          </div>\n          <div class=\"relative h-64 w-full\">\n            <canvas id=\"compMarginChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：“食人族”回购引擎与剪刀差 EPS 复利</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">10年注销 37% 股本 · 剩余回购授权 $1.7B (~23% 市值)</span>\n        </div>\n\n        <!-- 1. 财务健康度四大硬核指标卡 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-croxgreen-600 dark:text-croxgreen-400 uppercase\">Adjusted Gross Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">60.3%</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              剔除 26Q3 一次性 $64M 关税退税（推升当季 GAAP 毛利率至 66.2%）后，常态化毛利率稳守 60% 黄金线之上。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">TTM Free Cash Flow</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$754M</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              全年资本开支仅 <strong>$70M–$80M</strong>，轻资产注塑外包模式令自由现金流收益率高达 <strong>~10.4%</strong>。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Net Leverage Ratio</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~1.1x</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              账面现金 $163.5M，长期债务已从收购 HEYDUDE 初期的 $29亿 大幅削减至 <strong>~$12.3亿</strong>，处于 1.0x–1.5x 舒适走廊下沿。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Cannibal Share Buyback</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">-37% 股本</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              FY25 回购 $577M，26Q3 单季加速回购 <strong>$250M</strong>（稀释股本同比锐减 11.9% 至 46M），剩余授权仍高达 <strong>$1.7B</strong>。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互式 Chart.js 剪刀差复利双轴图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2021–FY2027E 调整后摊薄 EPS 攀升与稀释股本持续萎缩“剪刀差”效应</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">查理·芒格推崇的“食人族企业（Cannibal）”典范：流通股本由 63.2M 骤降至 ~46.0M 并向 42M 迈进，强力增厚每股内在价值</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-croxgreen-600 dark:text-croxgreen-400 bg-croxgreen-500/15 px-2.5 py-1 rounded\">26Q3 流通股同比 -11.9%</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"valEvolutionChart\"></canvas>\n          </div>\n        </div>\n\n        <!-- 3. 内嵌交互式「CROX 股票回购注销与 EPS 复利推演器」 -->\n        <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-7 text-white border border-slate-700 shadow-lg no-print\">\n          <div class=\"flex flex-wrap items-center justify-between gap-2 mb-5\">\n            <div>\n              <span class=\"text-[11px] font-mono uppercase tracking-wider text-croxgreen-400 font-bold\">Interactive Buyback & EPS Compounding Model</span>\n              <h3 class=\"text-lg font-bold text-white mt-0.5\">CROX 3年期“食人族”股票回购注销与目标股价推演器</h3>\n            </div>\n            <span class=\"text-xs px-3 py-1 rounded-full bg-white/10 text-slate-200 border border-white/15 font-mono\">基准：当前股价 $163.72 · FY26E EPS $14.55</span>\n          </div>\n\n          <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n            <!-- 四个调节滑块 -->\n            <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-5 text-xs\">\n              <div class=\"bg-navy-950/60 p-4 rounded-xl border border-slate-800\">\n                <div class=\"flex justify-between text-slate-300 mb-2\">\n                  <span>年度基准自由现金流 (FCF)</span>\n                  <span id=\"sim-fcf-label\" class=\"font-mono font-bold text-croxgreen-400\">$780M</span>\n                </div>\n                <input id=\"sim-fcf\" type=\"range\" min=\"600\" max=\"1000\" step=\"20\" value=\"780\" oninput=\"runCannibalSim()\" class=\"w-full accent-[#A3E635] cursor-pointer\">\n                <div class=\"flex justify-between text-[10px] text-slate-500 mt-1\"><span>保守 $600M</span><span>强劲 $1,000M</span></div>\n              </div>\n\n              <div class=\"bg-navy-950/60 p-4 rounded-xl border border-slate-800\">\n                <div class=\"flex justify-between text-slate-300 mb-2\">\n                  <span>FCF 用于股票回购比例</span>\n                  <span id=\"sim-ratio-label\" class=\"font-mono font-bold text-teal-400\">70%</span>\n                </div>\n                <input id=\"sim-ratio\" type=\"range\" min=\"30\" max=\"90\" step=\"5\" value=\"70\" oninput=\"runCannibalSim()\" class=\"w-full accent-[#22D3EE] cursor-pointer\">\n                <div class=\"flex justify-between text-[10px] text-slate-500 mt-1\"><span>优先还债 30%</span><span>激进回购 90%</span></div>\n              </div>\n\n              <div class=\"bg-navy-950/60 p-4 rounded-xl border border-slate-800\">\n                <div class=\"flex justify-between text-slate-300 mb-2\">\n                  <span>假设回购均价与期末 P/E 倍数</span>\n                  <span id=\"sim-pe-label\" class=\"font-mono font-bold text-amber-400\">12.0x</span>\n                </div>\n                <input id=\"sim-pe\" type=\"range\" min=\"9\" max=\"16\" step=\"0.5\" value=\"12.0\" oninput=\"runCannibalSim()\" class=\"w-full accent-[#FBBF24] cursor-pointer\">\n                <div class=\"flex justify-between text-[10px] text-slate-500 mt-1\"><span>低估越跌越买 9x</span><span>估值修复 16x</span></div>\n              </div>\n\n              <div class=\"bg-navy-950/60 p-4 rounded-xl border border-slate-800\">\n                <div class=\"flex justify-between text-slate-300 mb-2\">\n                  <span>内生净利润年化增速</span>\n                  <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400\">5.0%</span>\n                </div>\n                <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"10\" step=\"0.5\" value=\"5.0\" oninput=\"runCannibalSim()\" class=\"w-full accent-[#34D399] cursor-pointer\">\n                <div class=\"flex justify-between text-[10px] text-slate-500 mt-1\"><span>零增长 0%</span><span>双品牌发力 10%</span></div>\n              </div>\n            </div>\n\n            <!-- 推演结果输出面板 -->\n            <div class=\"lg:col-span-5 grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-1 gap-3\">\n              <div class=\"bg-white/5 rounded-xl p-4 border border-white/10 flex items-center justify-between\">\n                <div>\n                  <div class=\"text-xs text-slate-400\">3年累计注销股本比例</div>\n                  <div class=\"text-[11px] text-slate-500 mt-0.5\">总流通股缩减幅度</div>\n                </div>\n                <div id=\"sim-out-retired\" class=\"text-2xl font-mono font-extrabold text-croxgreen-400\">-18.8%</div>\n              </div>\n\n              <div class=\"bg-white/5 rounded-xl p-4 border border-white/10 flex items-center justify-between\">\n                <div>\n                  <div class=\"text-xs text-slate-400\">3年后 (FY29E) 预期 EPS</div>\n                  <div id=\"sim-out-eps-cagr\" class=\"text-[11px] text-teal-400 mt-0.5\">EPS 复合增速 +12.5%/年</div>\n                </div>\n                <div id=\"sim-out-eps\" class=\"text-2xl font-mono font-extrabold text-white\">$20.74</div>\n              </div>\n\n              <div class=\"bg-croxgreen-500/15 rounded-xl p-4 border border-croxgreen-400/40 flex items-center justify-between\">\n                <div>\n                  <div class=\"text-xs text-croxgreen-300 font-semibold\">3年期推演目标股价</div>\n                  <div id=\"sim-out-upside\" class=\"text-[11px] text-emerald-300 font-semibold mt-0.5\">潜在涨幅 +52.0%</div>\n                </div>\n                <div id=\"sim-out-price\" class=\"text-2xl font-mono font-extrabold text-croxgreen-400\">$248.90</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4. 华尔街多空分歧对比 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">双轮驱动重估</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>最大估值拖累项消除：</strong>此前市场因 HEYDUDE 连续下滑仅给 CROX 8x–9x 困境估值；如今 HEYDUDE 同比增长 +6.1% 且 Q4 指引 +10%~12%，估值具备向 13x–15x 重估的充足理由。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>国际高增长天花板极高：</strong>中、印、日及欧洲大陆渗透率仍低，国际业务占比已过半，结构性拉高集团整体有机增速。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>10.4% FCF Yield + $17亿回购形成强力推力：</strong>低估值时回购效率极高，即使营收仅个位数增长，股本快速萎缩仍可驱动双位数 EPS 复利。</span></li>\n            </ul>\n          </div>\n\n          <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">时尚周期与关税博弈</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>鞋履时尚潮流退潮担忧（Fad Risk）：</strong>历史上 Crocs 曾经历流行周期起伏，部分机构担忧北美经典款洞洞鞋已接近饱和上限。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>东南亚代工与跨境关税摩擦：</strong>供应链主要位于越南、印尼及亚洲，若美国进口关税政策再次反复，可能侵蚀部分毛利（尽管 26Q3 刚斩获 $64M 关税退税）。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>年内股价已自低点翻倍反弹：</strong>股价已从 52 周低点 $73.21 强劲回升至 $163.72 附近，短期获利盘丰厚，对后续财报连续超预期要求提高。</span></li>\n            </ul>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置框架 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-croxgreen-600 dark:text-croxgreen-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：基于 FY27E EPS ~$16.10 的三情景推演</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：高现金流价值成长核心仓 · 逢回调分批吸筹</span>\n        </div>\n\n        <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 牛市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-croxgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-croxgreen-600 dark:text-croxgreen-400\">概率：30%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">$225 – $242 <span class=\"text-xs font-normal text-slate-500\">(14x–15x P/E)</span></div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>Crocs 国际业务延续 12%–15% 双位数高增，HEYDUDE 稳固在中高个位数正增长，营业利润率维持 23%+，估值倍数向特色鞋履同行（DECK/BIRK）折中修复。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-croxgreen-600 dark:text-croxgreen-400\">\n              潜在上行空间：+37% 至 +48%（业绩与估值戴维斯双击）\n            </div>\n          </div>\n\n          <!-- 基准情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">$193 – $209 <span class=\"text-xs font-normal text-slate-500\">(12x–13x P/E)</span></div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>Crocs 主品牌全球稳增 ~4%–5%，HEYDUDE 保持低个位数稳健增长，每年动用 $5.5亿–$6.5亿 自由现金流回购注销 7%–9% 股本，FY27E EPS 顺利兑现 ~$16.10。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n              潜在上行空间：+18% 至 +28%（回购增厚驱动确定性收益）\n            </div>\n          </div>\n\n          <!-- 熊市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">$130 – $145 <span class=\"text-xs font-normal text-slate-500\">(8.5x–9.5x P/E)</span></div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>北美中低收入消费显著走弱，跨境关税成本再度上升拖累毛利率跌破 58%，或 HEYDUDE 补库过后二次放缓，估值退守个位数防守区间。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n              潜在下行回撤：-11% 至 -20%（10%+ FCF 回购构筑强力托底）\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构对冲缓释策略</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 时尚潮流与经典款审美疲劳风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">北美 Classic Clog 高渗透率下的流行周期波动</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                休闲鞋履天然受青少年审美变迁影响。公司正通过快速扩充时尚凉鞋（Brooklyn/Getaway）、机能运动廓形（Echo）以及高频 IP 鞋花更新，降低对单一经典洞洞鞋的依赖度。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 跨境贸易与关税政策反复风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">东南亚制造基地对美出口潜在关税扰动</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                虽然 26Q3 受益于 $64M 关税退税提振，但全球贸易关税环境仍具不确定性。好在 Crocs 单双注塑出厂成本（FOB）极低（仅占终端零售价约 15%–18%），轻微提价 $3–$5 即可完全吸收潜在关税冲击。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 北美批发商下单谨慎与消费分层</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">美国传统鞋类连锁零售商库存管理趋严</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                Foot Locker、Famous Footwear 等北美家庭鞋履连锁渠道客流存在季节波动；CROX 依托 53.5% 的高 DTC 直营占比与快反补货能力保持渠道库存高度健康。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · HEYDUDE 终端动销持续性验证风险</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">批发补库大增 +14% 后需验证终端全价动销率</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                26Q3 HEYDUDE 扭亏转正主要由批发渠道 +14% 拉动，后续假日季（Q4）需密切确认终端门店 Sell-through（售罄率）与 DTC 同店增速同步走强，巩固反转成色。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 机构级仓位配置建议 -->\n        <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n          <h3 class=\"text-base font-bold text-croxgreen-400 mb-4 flex items-center space-x-2\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n            <span>机构级投资组合仓位配置与交易纪律建议</span>\n          </h3>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-white mb-1\">1. GARP 价值成长核心仓（Core Allocation）</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                在美股可选消费普遍处于 22x–30x 高估值的环境下，CROX 以 ~11.2x P/E 提供超 10% 自由现金流收益率与双位数 EPS 增速，是稀缺的<strong>高赔率 GARP 核心配置标的</strong>。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-croxgreen-400 mb-1\">2. 节奏把控与加仓锚点（10.0x–11.5x P/E）</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                考虑到股价刚创 52 周新高（$163.72），建议建立基础底仓后，<strong>若因宏观零售数据波动回调至 $148–$156（对应约 10x FY26E P/E）果断加码</strong>，与公司 $17亿 回购盘同向共振。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-teal-400 mb-1\">3. 消费组合跨风格配对策略</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                可将 CROX（$50–$60 大众抗通胀口红效应 + 激进回购）与高估值中产运动品牌（如 ONON / DECK）配对组合，平衡消费分层周期风险并显著提升组合整体现金流厚度。\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n          </div>\n          <div class=\"flex items-center space-x-2 no-print\">\n            <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-croxgreen-500/15 text-croxgreen-600 dark:text-croxgreen-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n            <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n            点击勾选机构季报追踪已验证达标的指标（状态通过本地存储自动保存），用高频基本面事实动态跟踪双品牌重估进度：\n          </p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#65A30D] focus:ring-croxgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. HEYDUDE 季度正增长持续性与 Q4 加速兑现</span>\n                  <span class=\"text-[11px] font-mono text-croxgreen-600 dark:text-croxgreen-400 font-semibold shrink-0\">估值重估第一锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  继 26Q3 实现 +6.1% 反转后，重点验证 26Q4 假日季营收能否如期兑现 +10%–12% 指引且 DTC 同店同步改善。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#65A30D] focus:ring-croxgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. Crocs 国际市场双位数增长与国际 DTC 斜率</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">长周期成长引擎</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪中国、印度、日本及西欧一级市场扩张，确保国际板块延续 10%+ 增长（26Q3 国际整体 +12%，国际 DTC +24%）。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#65A30D] focus:ring-croxgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 季度股票回购执行力度与流通股缩减速度</span>\n                  <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">EPS 增厚放大器</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  26Q3 单季回购达 $250M、股本同比减少 11.9%，持续追踪 $17亿 剩余回购授权在未来 6–8 个季度的消耗进度。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#65A30D] focus:ring-croxgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 剔除退税后的内生调整后毛利率稳守 59%–61%</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">品牌定价权指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  剔除 $64M 关税退税一次性利好后，观察促销折扣控制、Jibbitz 连带率及供应链转移对 60% 毛利率中枢的支撑力。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#65A30D] focus:ring-croxgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 北美 DTC 同店转化率及 AI 助手 Rivet 变现效率</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">数字化直营指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测 TikTok Shop 直播带货GMV表现，以及官网 AI 导购 Agent “Rivet” 对转化率、退货率降低及鞋花交叉销售的量化贡献。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#65A30D] focus:ring-croxgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 库存周转健康度与净债务杠杆率维持 ~1.0x</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">资产质量安全垫</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  确保期末库存同比增速持续低于下一季预期营收增速，且净债务/调整后 EBITDA 稳定在 1.0x–1.3x 低风险区间。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>卡骆驰 Crocs, Inc. (NASDAQ: CROX) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：2026 Q3 财报及 2026 年 11 月市场一致预期 (FY26E–FY27E)</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开定期报告（10-Q/10-K）、业绩电话会指引及全球鞋服零售行业调研数据整理生成，旨在提供结构化的商业模式解析与估值研究框架。报告中涉及的 FY2026E–FY2027E 盈利预测、股票回购复利推演模型及三情景目标价区间均基于特定财务假设，不构成任何具体的证券买卖建议、要约或收益承诺。市场有风险，投资决策前请结合自身风险承受能力独立审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与左侧导航滚动联动高亮 (Scroll-Spy)\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-croxgreen-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-croxgreen-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-croxgreen-400', 'text-navy-950', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-croxgreen-400', 'text-navy-950', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. “食人族”股票回购注销与 EPS 复利推演器\n    // ==========================================\n    function runCannibalSim() {\n      const baseFCF = parseFloat(document.getElementById('sim-fcf').value); // $M\n      const buybackRatio = parseFloat(document.getElementById('sim-ratio').value) / 100;\n      const assumedPE = parseFloat(document.getElementById('sim-pe').value);\n      const organicGrowth = parseFloat(document.getElementById('sim-growth').value) / 100;\n\n      document.getElementById('sim-fcf-label').textContent = `$${baseFCF}M`;\n      document.getElementById('sim-ratio-label').textContent = `${Math.round(buybackRatio * 100)}%`;\n      document.getElementById('sim-pe-label').textContent = `${assumedPE.toFixed(1)}x`;\n      document.getElementById('sim-growth-label').textContent = `${(organicGrowth * 100).toFixed(1)}%`;\n\n      const currentPrice = 163.72;\n      const initialShares = 44.4; // M shares ($7.27B / $163.72)\n      const baseEPS = 14.55;      // FY26E Adj EPS midpoint\n      let netIncome = initialShares * baseEPS; // ~$646M\n      let shares = initialShares;\n\n      for (let yr = 1; yr <= 3; yr++) {\n        netIncome = netIncome * (1 + organicGrowth);\n        const currentYrFCF = baseFCF * Math.pow(1 + organicGrowth, yr - 1);\n        const buybackCash = currentYrFCF * buybackRatio;\n        const preBuybackEPS = netIncome / shares;\n        const avgBuybackPrice = preBuybackEPS * assumedPE;\n        const retired = buybackCash / avgBuybackPrice;\n        shares = Math.max(15.0, shares - retired);\n      }\n\n      const finalEPS = netIncome / shares;\n      const targetPrice = finalEPS * assumedPE;\n      const retiredPct = ((initialShares - shares) / initialShares) * 100;\n      const epsCagr = (Math.pow(finalEPS / baseEPS, 1 / 3) - 1) * 100;\n      const upsidePct = ((targetPrice - currentPrice) / currentPrice) * 100;\n\n      document.getElementById('sim-out-retired').textContent = `-${retiredPct.toFixed(1)}%`;\n      document.getElementById('sim-out-eps').textContent = `$${finalEPS.toFixed(2)}`;\n      document.getElementById('sim-out-eps-cagr').textContent = `EPS 复合增速 +${epsCagr.toFixed(1)}%/年`;\n      document.getElementById('sim-out-price').textContent = `$${targetPrice.toFixed(2)}`;\n\n      const upsideEl = document.getElementById('sim-out-upside');\n      if (upsidePct >= 0) {\n        upsideEl.textContent = `较现价潜在涨幅 +${upsidePct.toFixed(1)}%`;\n        upsideEl.className = 'text-[11px] text-emerald-300 font-semibold mt-0.5';\n      } else {\n        upsideEl.textContent = `较现价潜在回撤 ${upsidePct.toFixed(1)}%`;\n        upsideEl.className = 'text-[11px] text-rose-400 font-semibold mt-0.5';\n      }\n    }\n\n    // ==========================================\n    // 6. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'crox_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略存储读取限制\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略存储写入限制\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 7. Chart.js 数据可视化初始化与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'evolution';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 视图 A：FY2021–FY2027E 双品牌营收演进（堆叠柱状图）\n      const evoConfig = {\n        type: 'bar',\n        data: {\n          labels: ['FY2021', 'FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n          datasets: [\n            {\n              label: 'Crocs 卡骆驰主品牌 ($B)',\n              data: [2.31, 2.66, 3.01, 3.28, 3.33, 3.45, 3.60],\n              backgroundColor: '#65A30D',\n              borderRadius: 4,\n            },\n            {\n              label: 'HEYDUDE 休闲鞋品牌 ($B)',\n              data: [0.00, 0.90, 0.95, 0.82, 0.715, 0.715, 0.755],\n              backgroundColor: '#06B6D4',\n              borderRadius: 4,\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              max: 5.0,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' }\n            }\n          }\n        }\n      };\n\n      // 视图 B：FY2026E 多维区域与渠道营收拆解（横向柱状图）\n      const splitConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            '按品牌区域：Crocs 国际市场 (高速领跑)',\n            '按品牌区域：Crocs 北美市场 (高利现金牛)',\n            '按品牌区域：HEYDUDE 全球营收 (触底回升)',\n            '按销售渠道：DTC 直营渠道 (占比 53.5%)',\n            '按销售渠道：批发分销渠道 (占比 46.5%)'\n          ],\n          datasets: [\n            {\n              label: 'FY2026E 营收体量 ($B)',\n              data: [1.76, 1.70, 0.72, 2.23, 1.93],\n              backgroundColor: [\n                '#65A30D',\n                '#3B82F6',\n                '#06B6D4',\n                '#10B981',\n                '#6366F1'\n              ],\n              borderRadius: 6,\n              barThickness: 24\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `FY26E 规模: ~$${ctx.parsed.x.toFixed(2)}B (占集团总营收 ${(ctx.parsed.x / 4.16 * 100).toFixed(1)}%)`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 2.6,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnEvo = document.getElementById('btn-chart-evo');\n      const btnSplit = document.getElementById('btn-chart-split');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'evolution') {\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-croxgreen-600 dark:text-croxgreen-400 shadow-sm transition cursor-pointer';\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n        titleEl.textContent = 'FY2021–FY2027E 双品牌营收演进与 HEYDUDE 触底回升';\n        subEl.textContent = 'Crocs 主品牌稳步迈向 $3.60B，HEYDUDE 历经两年渠道出清后于 26H2 重回正增长轨道';\n      } else {\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-croxgreen-600 dark:text-croxgreen-400 shadow-sm transition cursor-pointer';\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n        titleEl.textContent = 'FY2026E（~$4.16B）区域版图与全渠道收入结构拆解';\n        subEl.textContent = 'Crocs 国际营收（~$1.76B）反超北美，DTC 直营渠道贡献达 53.5%';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            '单品毛利与注塑制造极简度',\n            '社交病毒传播与DIY粘性',\n            '自由现金流转化率 (FCF)',\n            '抗通胀价格带韧性 ($50-$60)',\n            '全球化空白市场扩张空间'\n          ],\n          datasets: [\n            {\n              label: 'Crocs (CROX)',\n              data: [9.8, 9.5, 9.6, 9.4, 8.9],\n              borderColor: '#65A30D',\n              backgroundColor: 'rgba(101, 163, 13, 0.24)',\n              pointBackgroundColor: '#65A30D',\n              borderWidth: 2.5\n            },\n            {\n              label: 'Deckers / Birkenstock (高端特色鞋履)',\n              data: [8.6, 8.2, 8.0, 6.8, 8.7],\n              borderColor: '#3B82F6',\n              backgroundColor: 'rgba(59, 130, 246, 0.14)',\n              pointBackgroundColor: '#3B82F6',\n              borderWidth: 1.8\n            },\n            {\n              label: 'Nike / 传统大众运动鞋企',\n              data: [6.0, 7.6, 6.5, 6.2, 6.8],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.12)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initCompMarginChart() {\n      const ctx = document.getElementById('compMarginChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (compMarginChartInstance) compMarginChartInstance.destroy();\n      compMarginChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            'Deckers (DECK · P/E ~24.5x)',\n            'Crocs (CROX · P/E ~11.2x ★)',\n            'Birkenstock (BIRK · P/E ~22.8x)',\n            'On Holding 昂跑 (ONON · P/E ~35.0x)',\n            'Skechers 斯凯奇 (SKX · 大众休闲)',\n            'Nike 耐克 (NKE · P/E ~26.0x)'\n          ],\n          datasets: [{\n            label: '调整后营业利润率 Operating Margin (%)',\n            data: [23.7, 22.5, 21.0, 13.2, 9.4, 8.4],\n            backgroundColor: [\n              '#3B82F6',\n              '#65A30D',\n              '#06B6D4',\n              '#6366F1',\n              '#64748B',\n              '#94A3B8'\n            ],\n            borderRadius: 6,\n            barThickness: 22\n          }]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `营业利润率: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 28,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initValEvolutionChart() {\n      const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n      valEvolutionChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['FY2021', 'FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '调整后摊薄 EPS ($/股)',\n              data: [8.32, 10.92, 12.03, 13.17, 12.51, 14.55, 16.10],\n              backgroundColor: 'rgba(101, 163, 13, 0.85)',\n              borderRadius: 5,\n              barThickness: 26,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '加权平均稀释股本 (百万股)',\n              data: [63.2, 62.1, 61.2, 59.5, 52.2, 46.0, 42.1],\n              borderColor: '#06B6D4',\n              backgroundColor: '#06B6D4',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}`\n                  : `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(1)}M 股`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              min: 0,\n              max: 20,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v },\n              title: { display: true, text: '调整后摊薄 EPS ($)', color: colors.text, font: { size: 11 } }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 35,\n              max: 70,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#06B6D4', font: { size: 11, weight: '600' }, callback: v => v + 'M' },\n              title: { display: true, text: '稀释流通股本 (百万股)', color: '#06B6D4', font: { size: 11 } }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initCompMarginChart();\n      initValEvolutionChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      runCannibalSim();\n      initBizChart();\n      initRadarChart();\n      initCompMarginChart();\n      initValEvolutionChart();\n    });\n  </script>\n</body>\n</html>"};
